import ast, json

ROOT = "/home/johnson/workspace/LLM_PostProcess"
CORPUS = f"{ROOT}/research/ai-infra-expert/corpus/train.jsonl"
EXP = f"{ROOT}/experiments/2026-08-17-teacher-b-corpus-review"
OUT = f"{EXP}/results/train-batch-0192.jsonl"
START = 1910
N = 10

src = open(f"{EXP}/scripts/tb_gen_batch_0182.py").read()
tree = ast.parse(src)
COMMON_TAIL = None
for node in tree.body:
    if isinstance(node, ast.Assign) and getattr(node.targets[0], "id", "") == "COMMON_TAIL":
        COMMON_TAIL = ast.literal_eval(node.value)
assert COMMON_TAIL and len(COMMON_TAIL) > 2000

rows = [json.loads(l) for l in open(CORPUS) if l.strip()]
sel = rows[START:START + N]
assert len(sel) == N

STANCES = [
    ("Analytical stance under test: memory-byte-accounting-first - the claimed memory saving must be reconciled against a full device budget.",
     "Falsifiable hypothesis H81: the device memory freed by the quantized arm equals the measured weight-byte reduction minus the resident cost of scales, zero points and any dequantization workspace, and that freed memory converts into additional KV-cache blocks in a measurable, reported ratio. If the observed free memory differs materially from that reconciliation, unaccounted allocations exist and the capacity claim is not yet derived.",
     "A memory claim stated as a compression ratio on paper is not the same quantity as free bytes on the device, and the gap between them is where capacity plans fail. Build a full budget on both arms from the allocator's own accounting: weights, quantization metadata such as per-group scales and zero points, activation and workspace peaks, CUDA graph buffers, fragmentation overhead, the framework and driver context, and the KV cache that consumes whatever remains. Quantization metadata is real resident memory whose size grows as group size shrinks, so a finer grouping that improves accuracy simultaneously erodes the saving it was adopted for; report the metadata bytes explicitly rather than folding them into a nominal bits-per-weight figure. Then state what the freed bytes are actually for, because free memory that is not converted into KV-cache blocks or a higher memory-utilisation fraction produces no serving benefit at all and merely idles. Convert the freed bytes into a concrete admitted-concurrency figure using the per-token KV byte cost at the deployed parallel degree and context length, and verify that figure against measured admitted concurrency rather than asserting it. Record peak rather than steady-state occupancy, since the arm survives or dies at its peak. ESTIMATE: additional concurrent sequences are approximately freed bytes divided by per-sequence KV bytes at the target context length; derivation is direct byte division ignoring fragmentation, which makes it an optimistic ESTIMATE, not MEASURED. Rollback gate: no capacity claim without an allocator-level budget that reconciles to within a stated tolerance."),

    ("Analytical stance under test: numerical-outlier-mechanism-first - name the mechanism by which quantization error becomes quality error.",
     "Falsifiable hypothesis H82: quality degradation in the quantized arm is concentrated in layers whose activation distributions carry high-magnitude outlier channels, testable by measuring per-layer quantization error against a BF16 reference on identical inputs and correlating it with per-layer outlier statistics. If degradation is uniform across layers and uncorrelated with outlier magnitude, the assumed mechanism is wrong and the mitigation chosen on that basis is unjustified.",
     "Treating quantization error as a scalar 'accuracy loss' prevents any diagnosis, because the actual damage is structured: a small number of channels with large dynamic range dominate the per-tensor scale, compress every other channel into few effective levels, and the resulting error propagates unevenly through depth. Measure it directly rather than inferring it from downstream scores. Run identical inputs through both arms with activation capture at layer boundaries, compute per-layer and per-channel error against the BF16 reference, and record the activation range statistics that drive scale selection. This localises the damage and tells you which mitigation is even applicable - finer grouping, per-channel rather than per-tensor scaling, keeping designated sensitive layers in higher precision, or a transformation that redistributes outliers before quantization - each of which has a different memory and kernel-support cost that must then be re-entered into the byte and dispatch accounting. Note that error at a layer boundary does not linearly predict end-to-end quality, so the layer-level measurement is a diagnostic that generates hypotheses, not a substitute for the end-to-end evaluation; state that relationship explicitly rather than letting a low per-layer error stand in for a quality result. ESTIMATE: effective quantization levels available to non-outlier channels shrink roughly in proportion to the ratio between the outlier magnitude and the typical channel magnitude under a shared scale; derivation is that a shared scale is set by the maximum, and it is an ESTIMATE, not MEASURED."),

    ("Analytical stance under test: statistical-power-and-noise-floor-first - establish what difference the harness can even resolve.",
     "Falsifiable hypothesis H83: the measured BF16-versus-quantized quality delta exceeds the harness noise floor, established by an A/A comparison in which two identically configured BF16 runs are compared using the same evaluation set, seeds and statistics. If the A/A spread is comparable to the A/B delta, the study has no resolving power at the effect size being claimed and must be re-run with more evaluation items or more repetitions.",
     "A comparison reported without a noise floor cannot distinguish a real effect from run-to-run variation, and on serving benchmarks that variation is frequently larger than the effect under discussion. Run the A/A control first: two identical arms, same seeds where determinism is available, same evaluation set, same statistics, executed interleaved so drift is shared. The observed A/A spread is the resolution limit of the harness, and any A/B delta inside it is uninterpretable regardless of how it is presented. Then size the study rather than accepting whatever the default evaluation set provides: state the minimum effect worth acting on, and compute the number of evaluation items and repetitions needed to resolve it at the chosen confidence, treating that computation as a pre-registered input rather than a post hoc justification. Report confidence intervals computed across repeated runs rather than across items within a single run, because within-run item variance systematically understates run-level uncertainty. Where sampling is stochastic, either fix seeds and report the fixed-seed result as a single draw, or repeat across seeds and report the distribution; do not present one stochastic draw as the arm's behaviour. ESTIMATE: the evaluation-item count required to resolve an effect grows roughly with the inverse square of the effect size for a fixed confidence level; derivation is the standard error scaling with the square root of sample size, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption on a delta that has not been shown to exceed the A/A noise floor."),

    ("Analytical stance under test: traffic-representativeness-first - the request mix is an input to the result, not a background detail.",
     "Falsifiable hypothesis H84: the qualification workload reproduces production's joint distribution of input length, output length, arrival pattern, concurrency and prompt-cache hit rate within a pre-registered tolerance, verified by replaying sampled production traces and comparing distributions. If the synthetic workload differs materially, the measured throughput and latency deltas describe a workload that no one serves.",
     "Quantization's benefit is concentrated in decode, so the measured end-to-end gain is a direct function of how much of the workload is decode, which makes the request mix the dominant free parameter of the study. A fixed-length synthetic benchmark with uniform prompts and a single concurrency level will produce a clean number that does not transfer: short outputs suppress the decode share and understate the gain, long uniform outputs overstate it, and a constant arrival rate removes the burstiness that determines queueing and therefore the tail. Derive the workload from sampled production traces instead: preserve the joint distribution of input and output lengths rather than their marginals, preserve the arrival process including bursts, preserve the concurrency distribution, and preserve the prompt-cache hit rate, since a high cache hit rate removes prefill work and mechanically raises the decode share. Report results per traffic segment where segments differ materially, because a single blended number can hide a regression in a small but critical segment. Record the trace window, its date range and any sampling or anonymisation applied, so the workload itself is a versioned artefact that can be re-run when the mix shifts. ESTIMATE: end-to-end gain scales approximately with the decode share of total step time, so a workload whose decode share differs by a factor from production will misstate the gain by a similar factor; derivation is time-share weighting, and it is an ESTIMATE, not MEASURED."),

    ("Analytical stance under test: rollout-mechanics-first - the comparison must specify how the change reaches and leaves production.",
     "Falsifiable hypothesis H85: the quantized artefact can be rolled forward to a stated traffic fraction and rolled back to BF16 within a pre-registered time bound, demonstrated by an actual rehearsed rollback in a production-like environment rather than asserted from a runbook. If the rehearsal misses the bound, the change is not safely deployable regardless of its benchmark result.",
     "A fair comparison that ends at a benchmark table omits the operational half of the decision: the cost and risk of getting the change in and out. Specify the rollout mechanism concretely - shadow traffic, canary at a stated percentage, progressive ramp with defined soak at each step - and specify what is monitored at each step with thresholds that trigger an automatic halt rather than a discussion. The rollback path deserves the same rigour: keep the BF16 artefact resident and warm rather than assuming it can be re-pulled and re-loaded under incident pressure, account for the model-load and warmup time that dominates recovery, and account for the capacity headroom needed to run both arms during the transition, which is a real cost the benchmark comparison never shows. Rehearse the rollback at least once and record the measured time to restore, because an unrehearsed rollback path is an assumption rather than a control. Note the state that does not roll back cleanly: cached responses generated by the quantized arm, downstream artefacts derived from its outputs, and any client behaviour adapted to its formatting, all of which persist after the model is reverted and must be enumerated. ESTIMATE: time to restore is dominated by artefact fetch plus model load plus warmup, so keeping the reference artefact warm removes the largest term; derivation is summing the serial steps of the restore path, and it is an ESTIMATE, not MEASURED. Rollback gate: no ramp beyond canary until a measured restore time is on record."),

    ("Analytical stance under test: reproducibility-and-artefact-identity-first - a result that cannot be re-derived is not a result.",
     "Falsifiable hypothesis H86: an independent operator, given only the recorded artefact manifest and procedure, reproduces every headline metric within a pre-registered band on a fresh environment. If reproduction falls outside the band, an unrecorded input is controlling the result and must be identified before the comparison is used for a decision.",
     "Quantization studies are unusually easy to make irreproducible because the artefact is derived rather than downloaded, and the derivation depends on a toolchain that moves. Pin identity by content hash rather than by name: the base checkpoint, the quantized checkpoint, the calibration set, the quantization tool and its version, the engine, kernel library, driver and CUDA versions, the container image digest, the hardware SKU, the parallel degree, the scheduler and decoding configuration, the evaluation set, and the seeds. A tag or a branch name is not identity, and a recipe described in prose is not a procedure. Store the exact command lines and configuration files alongside the results in one bundle, and verify the bundle by having someone who did not run the study reproduce it from the bundle alone. Expect and document the sources of legitimate nondeterminism - reduction order in collectives, kernel autotuning selections, and stochastic decoding - and state which metrics are exactly reproducible and which are reproducible only in distribution, since conflating the two produces false reproduction failures that erode trust in the process. Retain raw generations and per-request records, not only aggregates, because a later dispute is almost always about a specific behaviour that aggregates cannot adjudicate. ESTIMATE: the probability of a reproduction failure rises with the number of unpinned inputs, since each unpinned input is an independent opportunity for drift; derivation is treating each input as an independent failure source, and it is an ESTIMATE, not MEASURED."),

    ("Analytical stance under test: alternative-hypothesis-first - compare quantization against the other ways to reach the same cost target.",
     "Falsifiable hypothesis H87: at the pre-registered cost target and SLO, weight-only quantization dominates the enumerated alternatives - a smaller base model, better batching and scheduling configuration, prompt-cache and prefix-cache exploitation, speculative decoding, or simply a different hardware SKU - on the same cost-per-token metric measured under the same conditions. If any alternative reaches the target at lower total cost including qualification effort, the quantization project is not the right instrument even if it works.",
     "The stated objective is lower serving cost, and quantization is one instrument among several, so a comparison scoped only to BF16 versus quantized answers a narrower question than the one asked. Enumerate the alternatives explicitly and cost them on the same metric at the same SLO attainment: a smaller model of the same family, which changes quality on the same axes and is often qualified faster; scheduler and batching tuning, including memory-utilisation fraction, chunked prefill and maximum batch size, which frequently yields a substantial gain at negligible qualification cost and should therefore be applied to the BF16 baseline before any comparison is run; prefix and prompt caching, whose benefit depends on the traffic's shared-prefix structure and is measurable from traces before any model change; speculative decoding, which trades acceptance rate for step count; and a different accelerator SKU with different bandwidth-to-cost characteristics. Note the confounding risk directly: if the BF16 baseline is untuned, part of the measured quantization gain is really a scheduler gain, and the study will attribute it to precision. Applying the cheap tuning to both arms first is what makes the comparison about precision. These options are not mutually exclusive, so also record which combine and which conflict. ESTIMATE: an untuned baseline can absorb a meaningful share of the apparent quantization gain, which is why baseline tuning precedes the comparison; derivation is that both changes act on the same decode-time budget, and it is an ESTIMATE, not MEASURED."),

    ("Analytical stance under test: fairness-and-safety-regression-first - aggregate quality can hold while specific populations regress.",
     "Falsifiable hypothesis H88: refusal behaviour, safety-classifier agreement and per-language and per-domain quality on the quantized arm match BF16 within pre-registered per-slice tolerances, not merely in aggregate. If any slice regresses beyond tolerance while the aggregate holds, the aggregate is masking a targeted degradation and adoption is blocked for that slice.",
     "Aggregate quality metrics average over populations, and quantization error is not distributed uniformly across them: low-resource languages, code, long-context reasoning and safety-relevant refusal behaviour are represented by different activation statistics than the calibration data typically captures, so they degrade first and are the least likely to appear in a headline score. Pre-register the slices before measuring, size each slice to have resolving power on its own rather than relying on the aggregate's sample count, and report per-slice deltas with per-slice tolerances. Treat safety behaviour as a distinct axis rather than a quality sub-score: measure refusal rate on a held-out adversarial set, measure agreement with the production safety classifier, and check both over-refusal and under-refusal, since quantization can shift the decision boundary in either direction and both directions are incidents. Record who owns the safety verdict and require it to be independent of the cost objective driving the change. Where a slice regresses, the honest outcomes are scoping adoption away from that slice or rejecting the artefact, not reweighting the aggregate until the result passes. ESTIMATE: slices whose distribution is least represented in the calibration set are the most likely to regress, because quantization parameters are fitted statistics of the calibration distribution; derivation is the estimation-under-distribution-mismatch argument, and it is an ESTIMATE, not MEASURED. Rollback gate: any safety-slice regression beyond tolerance blocks adoption outright."),

    ("Analytical stance under test: warmup-steady-state-and-measurement-hygiene-first - most of the disputed numbers are measurement artefacts.",
     "Falsifiable hypothesis H89: the reported per-arm metrics are steady-state values, verified by discarding a pre-registered warmup period and showing that the retained window's metric is stationary across sub-windows. If sub-window metrics trend, the run had not reached steady state and the reported number is a transient rather than the arm's behaviour.",
     "Serving measurements are easy to get wrong in ways that produce confident, wrong numbers, and quantized arms are especially exposed because kernel autotuning, CUDA graph capture and lazy allocation all concentrate cost in the first requests. Define the measurement protocol before running: a warmup phase that is executed and discarded, a fixed measurement window, a check that per-sub-window metrics are stationary, and repetition across independent process launches rather than repeated windows within one launch, since a single launch shares one autotune outcome and one allocator state. Separate the load generator from the server and verify the generator is not itself the bottleneck by confirming that offered load is achieved rather than assumed; a saturated client silently caps both arms at the same number and erases the effect. Record timestamps and per-request records rather than only aggregates so the window can be re-cut during analysis. Control the host environment - power and clock state, thermal throttling, concurrent tenants, NUMA placement and CPU affinity - and record them, since clock throttling during a long run can produce a decline that looks like a model property. Interleave arms across repetitions so any drift is shared rather than assigned to one arm. ESTIMATE: first-request latency can exceed steady-state by a large factor due to autotuning, graph capture and allocation, which is why warmup discard is mandatory rather than optional; derivation is that these are one-off serial costs on the first execution path, and it is an ESTIMATE, not MEASURED."),

    ("Analytical stance under test: scope-and-generalisation-boundary-first - state in writing what the verdict does not cover.",
     "Falsifiable hypothesis H90: the qualification verdict holds only within an explicitly recorded envelope of base model, engine version, kernel library, driver, hardware SKU, parallel degree, context length and traffic mix, and any deployment outside that envelope is treated as unqualified until re-measured. If a deployment outside the envelope is observed to inherit the verdict, the governance control has failed independently of whether the measurement was correct.",
     "The most expensive failure in this class of study is not a wrong number but a correct number applied to a configuration it never described. Quantization results do not transfer across hardware generations, because the availability and efficiency of low-precision kernels is a property of the device and its software stack; they do not transfer across parallel degrees, because the communication share of step time changes; they do not transfer across context lengths, because the KV-cache-to-weight byte ratio changes and with it the share of memory traffic that quantization touches; and they do not transfer across traffic mixes, because the decode share changes. Write the envelope into the artefact metadata as machine-readable constraints, and enforce it at deployment time rather than in a document, so a checkpoint cannot be scheduled onto an unqualified SKU or parallel degree without an explicit override that is logged and reviewed. Attach the re-qualification trigger list to the same metadata and give it an owner and a schedule. State the residual unknowns plainly, including which slices were not measured and which failure modes the study could not exclude, because a bundle that claims complete coverage cannot be audited and invites exactly the out-of-envelope reuse this control exists to prevent. ESTIMATE: the number of configurations sharing a single qualification grows quickly in a fleet with heterogeneous SKUs and parallel degrees, so machine-readable enforcement scales where documentation does not; derivation is combinatorial growth over the envelope dimensions, and it is an ESTIMATE, not MEASURED."),
]

out = []
for row, (stance, hyp, body) in zip(sel, STANCES):
    m = {x["role"]: x["content"] for x in row["messages"]}
    ans = f"{stance}\n\n{hyp}\n\n{body}{COMMON_TAIL}"
    out.append({
        "source_id": row["id"],
        "teacher_lane": "teacher-B",
        "teacher_model": "claude-opus-5-current",
        "calibration_status": "provisional",
        "decision": "rewrite",
        "source_user": m["user"],
        "source_assistant": m["assistant"],
        "corrected_answer": ans,
        "quality_dimensions": {
            "technical_correctness": 3,
            "instruction_coverage": 2,
            "operational_safety": 3,
        },
        "risks": [
            "source_assistant is a grading rubric rather than an answer; training on it teaches enumeration of evaluation criteria instead of performing the comparison",
            "memory saving is listed as a checklist item with no device-level byte budget, so quantization metadata, workspace and fragmentation are unaccounted and the capacity claim is underived",
            "no per-layer or per-channel error mechanism, so outlier-driven degradation cannot be localised and mitigation choices are unjustified",
            "no A/A noise floor or power sizing, so a delta smaller than harness variation can be reported as an effect",
            "workload representativeness is unspecified, and since the gain scales with decode share a synthetic mix can misstate it by a large factor",
            "no rollout or rehearsed rollback path, no reproducibility pinning by content hash, and no comparison against cheaper alternatives such as baseline scheduler tuning or prefix caching",
            "no per-slice safety, language and domain regression checks, no measurement hygiene protocol, and no written generalisation envelope enforcing where the verdict applies",
        ],
        "evidence_required": [
            "allocator-level memory budget on both arms covering weights, quantization scales and zero points, activation and workspace peaks, CUDA graph buffers, fragmentation and KV cache, reconciled against measured free bytes and converted to admitted concurrency",
            "per-layer and per-channel quantization error against a BF16 reference on identical inputs, with activation range and outlier statistics used to select mitigations",
            "A/A control run establishing the harness noise floor, plus a pre-registered power calculation stating evaluation-item count and repetition count for the minimum effect worth acting on",
            "production trace replay preserving the joint distribution of input and output lengths, arrival burstiness, concurrency and prompt-cache hit rate, with the trace window recorded as a versioned artefact",
            "rehearsed rollback with measured time to restore, canary and ramp thresholds with automatic halt, capacity headroom accounting for running both arms, and an enumeration of non-reverting state such as cached outputs",
            "content-hash artefact manifest pinning base and quantized checkpoints, calibration set, quantization tool, engine, kernel library, driver, container digest, hardware SKU, parallel degree and seeds, plus an independent reproduction within a stated band",
            "same-metric costing of alternatives at the same SLO attainment: smaller base model, scheduler and batching tuning applied to the baseline first, prefix and prompt caching, speculative decoding, alternative hardware SKU",
            "pre-registered per-slice quality, per-language, per-domain, refusal-rate and safety-classifier agreement results with per-slice tolerances and an independent safety verdict owner",
            "measurement protocol evidence: discarded warmup, stationarity check across sub-windows, repetition across independent process launches, verified non-saturated load generator, recorded clock and thermal state, interleaved arm ordering, and a machine-readable generalisation envelope with re-qualification triggers",
        ],
        "confidence": 0.62,
    })

with open(OUT, "w") as f:
    for r in out:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print("WROTE", OUT, len(out))
print("IDS", ",".join(r["source_id"] for r in out))
print("OPENINGS_DISTINCT", len({r["corrected_answer"][:200] for r in out}))
